      !$omp& reduction(+: tmp14, tmp15, tmp16) &
      !$omp& default(private)
      block
         real(wp) :: tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp37, tmp41, &
                     tmp20, tmp21, tmp22, tmp23, tmp24, tmp25

         !$omp do schedule(static)
         do j = 1, npt
            tmp26 = state%s4(j)
            tmp27 = state%s5(j)
            tmp28 = state%s6(j)
            tmp29 = state%s7(j)
            tmp30 = state%s8(j)
            tmp31 = state%s9(j)
            tmp32 = state%s11(j)
            tmp33 = state%s18(j)
            tmp34 = -tmp27
            tmp37 = -tmp28
            tmp41 = -tmp30
            tmp20 = 0.0_wp
            tmp21 = 0.0_wp
            tmp22 = 0.0_wp
            tmp23 = 0.0_wp
            tmp24 = 0.0_wp
            tmp25 = 0.0_wp
            !$omp simd &
            !$omp& reduction(+: tmp20, tmp21, tmp22, tmp23, tmp24, tmp25)
            do i = 1, j - 1
               block
                  real(wp) :: tmp35, tmp36, tmp38, tmp39, tmp40, tmp42, tmp43, tmp44, tmp45, &
                              tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, &
                              tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, &
                              tmp64, tmp65, tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, &
                              tmp73, tmp74, tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, &
                              tmp82, tmp83, tmp84, tmp85

                  tmp35 = state%s5(i) + tmp34
                  tmp36 = tmp26*tmp35
                  tmp38 = state%s6(i) + tmp37
                  tmp39 = tmp38*tmp29
                  tmp40 = tmp36 + tmp39
                  tmp42 = state%s8(i) + tmp41
                  tmp43 = tmp42*tmp31
                  tmp44 = tmp40 + tmp43
                  tmp45 = tmp44*tmp35
                  tmp46 = tmp35**(2)
                  tmp47 = tmp38**(2)
                  tmp48 = tmp46 + tmp47
                  tmp49 = tmp42**(2)
                  tmp50 = tmp48 + tmp49
                  tmp51 = 1.0_wp/sqrt(tmp50)
                  tmp52 = tmp51**(5)
                  tmp53 = tmp45*tmp52
                  tmp54 = (-3.0_wp)*tmp53
                  tmp55 = tmp51**(3)
                  tmp56 = tmp26*tmp55
                  tmp57 = tmp54 + tmp56
                  tmp58 = tmp57*state%s11(i)
                  tmp59 = tmp58*tmp33
                  tmp14(i) = tmp14(i) + tmp59
                  tmp60 = -tmp59
                  tmp20 = tmp20 + tmp60
                  tmp61 = tmp38*tmp44
                  tmp62 = tmp61*tmp52
                  tmp63 = (-3.0_wp)*tmp62
                  tmp64 = tmp29*tmp55
                  tmp65 = tmp63 + tmp64
                  tmp66 = tmp65*state%s11(i)
                  tmp67 = tmp66*tmp33
                  tmp15(i) = tmp15(i) + tmp67
                  tmp68 = -tmp67
                  tmp21 = tmp21 + tmp68
                  tmp69 = tmp42*tmp44
                  tmp70 = tmp69*tmp52
                  tmp71 = (-3.0_wp)*tmp70
                  tmp72 = tmp31*tmp55
                  tmp73 = tmp71 + tmp72
                  tmp74 = tmp73*state%s11(i)
                  tmp75 = tmp74*tmp33
                  tmp16(i) = tmp16(i) + tmp75
                  tmp76 = -tmp75
                  tmp22 = tmp22 + tmp76
                  tmp77 = tmp55*tmp35
                  tmp78 = tmp77*state%s11(i)
                  tmp79 = tmp78*tmp33
                  tmp23 = tmp23 + tmp79
                  tmp80 = tmp38*tmp55
                  tmp81 = tmp80*state%s11(i)
                  tmp82 = tmp81*tmp33
                  tmp24 = tmp24 + tmp82
                  tmp83 = tmp42*tmp55
                  tmp84 = tmp83*state%s11(i)
                  tmp85 = tmp84*tmp33
                  tmp25 = tmp25 + tmp85
               end block
            end do
            !$omp simd &
            !$omp& reduction(+: tmp20, tmp21, tmp22, tmp23, tmp24, tmp25)
            do i = j + 1, npt
               block
                  real(wp) :: tmp35, tmp36, tmp38, tmp39, tmp40, tmp42, tmp43, tmp44, tmp45, &
                              tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, &
                              tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, &
                              tmp64, tmp65, tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, &
                              tmp73, tmp74, tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, &
                              tmp82, tmp83, tmp84, tmp85

                  tmp35 = state%s5(i) + tmp34
                  tmp36 = tmp26*tmp35
                  tmp38 = state%s6(i) + tmp37
                  tmp39 = tmp38*tmp29
                  tmp40 = tmp36 + tmp39
                  tmp42 = state%s8(i) + tmp41
                  tmp43 = tmp42*tmp31
                  tmp44 = tmp40 + tmp43
                  tmp45 = tmp44*tmp35
                  tmp46 = tmp35**(2)
                  tmp47 = tmp38**(2)
                  tmp48 = tmp46 + tmp47
                  tmp49 = tmp42**(2)
                  tmp50 = tmp48 + tmp49
                  tmp51 = 1.0_wp/sqrt(tmp50)
                  tmp52 = tmp51**(5)
                  tmp53 = tmp45*tmp52
                  tmp54 = (-3.0_wp)*tmp53
                  tmp55 = tmp51**(3)
                  tmp56 = tmp26*tmp55
                  tmp57 = tmp54 + tmp56
                  tmp58 = tmp57*state%s11(i)
                  tmp59 = tmp58*tmp33
                  tmp14(i) = tmp14(i) + tmp59
                  tmp60 = -tmp59
                  tmp20 = tmp20 + tmp60
                  tmp61 = tmp38*tmp44
                  tmp62 = tmp61*tmp52
                  tmp63 = (-3.0_wp)*tmp62
                  tmp64 = tmp29*tmp55
                  tmp65 = tmp63 + tmp64
                  tmp66 = tmp65*state%s11(i)
                  tmp67 = tmp66*tmp33
                  tmp15(i) = tmp15(i) + tmp67
                  tmp68 = -tmp67
                  tmp21 = tmp21 + tmp68
                  tmp69 = tmp42*tmp44
                  tmp70 = tmp69*tmp52
                  tmp71 = (-3.0_wp)*tmp70
                  tmp72 = tmp31*tmp55
                  tmp73 = tmp71 + tmp72
                  tmp74 = tmp73*state%s11(i)
                  tmp75 = tmp74*tmp33
                  tmp16(i) = tmp16(i) + tmp75
                  tmp76 = -tmp75
                  tmp22 = tmp22 + tmp76
                  tmp77 = tmp55*tmp35
                  tmp78 = tmp77*state%s11(i)
                  tmp79 = tmp78*tmp33
                  tmp23 = tmp23 + tmp79
                  tmp80 = tmp38*tmp55
                  tmp81 = tmp80*state%s11(i)
                  tmp82 = tmp81*tmp33
                  tmp24 = tmp24 + tmp82
