            tmp15(j) = tmp15(j) + tmp21
            tmp16(j) = tmp16(j) + tmp22
            tmp17(j) = tmp17(j) + tmp23
            tmp18(j) = tmp18(j) + tmp24
            tmp19(j) = tmp19(j) + tmp25
         end do
         !$omp end do
      end block
      !$omp end parallel
      grad_r(1, :) = tmp14
      grad_r(2, :) = tmp15
      grad_r(3, :) = tmp16
      grad_n(1, :) = tmp17
      grad_n(2, :) = tmp18
