   !> DPCM (point charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs dpcm_point_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_point
      type(dpcm_point_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call dpcm_point_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, "[dpcm_point_response] call dpcm_point_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_point_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_point_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_point_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_point_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_point_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                      hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_point_response

   !> One direction of dpcm_point_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_point
      type(dpcm_point_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_point_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_point_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%a => state%a
      state%op1%c2 => state%s10
      tmp1 = state%a*dvn
      tmp2 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp1, tmp2, error)
      if (allocated(error)) return
      hvp_v = state%s12*tmp2
      tmp3 = 0.0_wp
      call state%solver%solve(state%op1, .true., dv, tmp3, error)
      if (allocated(error)) return
      tmp4 = state%s12*tmp3
      hvp_vn = tmp4*state%a
   end subroutine dpcm_point_response_one

   !> DPCM (point charges): energy derivatives with respect to the solvent parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs dpcm_point_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_param_weights(state, grad_eps, error)
      !> State of dpcm_point
      type(dpcm_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      real(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp5(:), tmp6(:)
      real(wp) :: tmp1, tmp3, tmp4, tmp7, tmp8, tmp9, tmp10

      if (state%matrix_free) then
         call dpcm_point_mf_param_weights(state, grad_eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, "[dpcm_point_param_weights] call dpcm_point_solve first")
         return
      end if
      allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_param_weights] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%a => state%a
      state%op1%c2 => state%s10
      tmp1 = state%s1**(-2)
      tmp2 = 0.5_wp*state%v
      tmp3 = dot(tmp2, state%s11)
      tmp4 = (-0.5_wp)*state%s2
      tmp5 = tmp4*state%s13
      tmp6 = state%a*state%s15
      tmp7 = dot(tmp5, tmp6)
      tmp8 = -tmp7
      tmp9 = tmp3 + tmp8
      tmp10 = tmp1*tmp9
      grad_eps = 2.0_wp*tmp10
   end subroutine dpcm_point_param_weights

   !> DPCM (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs dpcm_point_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_complex_medium(state, eps, error)
      !> State of dpcm_point
      type(dpcm_point_complex_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      complex(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp) :: tmp1, tmp2

      if (state%matrix_free) then
         call dpcm_point_complex_mf_medium(state, eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[dpcm_point_complex_medium] call dpcm_point_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_vn)) deallocate (state%cx_vn)
      if (allocated(state%cx_s11)) deallocate (state%cx_s11)
      if (allocated(state%cx_s13)) deallocate (state%cx_s13)
      if (allocated(state%cx_s14)) deallocate (state%cx_s14)
      if (allocated(state%cx_s15)) deallocate (state%cx_s15)
      if (allocated(state%cx_s17)) deallocate (state%cx_s17)
      if (allocated(state%cx_s18)) deallocate (state%cx_s18)
      if (allocated(state%cx_s19)) deallocate (state%cx_s19)
      if (allocated(state%cx_s20)) deallocate (state%cx_s20)
      if (allocated(state%cx_s21)) deallocate (state%cx_s21)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_vn(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s11(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s13(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s14(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s15(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s17(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s20(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_complex_medium] allocation failed")
         return
      end if
      state%cx_s11 = 0.0_wp
      state%cx_s13 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op3%npt = npt
      state%op3%npoint = npt
      state%op3%id = 3
      state%op3%points => state%r
      state%op3%a => state%a
      state%cx_s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%cx_s1
      tmp2 = (-2.0_wp)*tmp1
      state%cx_s2 = 1.0_wp + tmp2
      state%cx_s3 = -state%cx_s2
      state%op3%c1 = state%cx_s3
      state%op3%c2 => state%s10
      call state%solver%setup_complex(state%op3, error)
      if (allocated(error)) return
      state%cx_s12 = 0.5_wp*state%cx_s2

      state%cx_ready = 2
   end subroutine dpcm_point_complex_medium

   !> DPCM (point charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs dpcm_point_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_complex_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
      !> State of dpcm_point
      type(dpcm_point_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
      complex(wp), contiguous, intent(in) :: vn(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      complex(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:)
      complex(wp), allocatable :: tmp1(:), tmp5(:), tmp6(:), tmp7(:), tmp8(:), tmp9(:), tmp10(:)
      complex(wp) :: tmp4, tmp11

      if (state%matrix_free) then
         call dpcm_point_complex_mf_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[dpcm_point_complex_solve] call dpcm_point_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_solve] vn: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_complex_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c2 => state%s10
      state%cx_v = v
      state%cx_vn = vn
      tmp1 = state%a*state%cx_vn
      call state%solver%solve_complex(state%op3, .false., tmp1, state%cx_s11, error)
      if (allocated(error)) return
      call state%solver%solve_complex(state%op3, .true., state%cx_v, state%cx_s13, error)
      if (allocated(error)) return
      state%cx_s14 = state%cx_s12*state%cx_s13
      call gemv(state%s10, real(state%cx_s11, wp), tmp2, trans="t")
      call gemv(state%s10, aimag(state%cx_s11), tmp3, trans="t")
      state%cx_s15 = cmplx(tmp2, tmp3, wp)
      q = state%cx_s2*state%cx_s11
      tmp4 = sum(state%cx_v*q)
      energy = 0.5_wp*tmp4
      grad_v = state%cx_s12*state%cx_s11
      grad_vn = state%cx_s14*state%a
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp5 = 6.283185307179586_wp*state%cx_s11
         tmp6 = state%a*state%cx_s15
         tmp7 = state%cx_s3*tmp6
         tmp8 = tmp5 + tmp7
         tmp9 = -tmp8
         tmp10 = tmp1 + tmp9
         tmp11 = sum(state%cx_s14*tmp10)
         energy = energy + tmp11
      end if

      state%cx_ready = 3
   end subroutine dpcm_point_complex_solve

   !> DPCM (point charges): energy gradient with respect to the cavity inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs dpcm_point_complex_solve on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_complex_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, error)
      !> State of dpcm_point
      type(dpcm_point_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      complex(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      complex(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      complex(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      complex(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to a
      complex(wp), contiguous, intent(out) :: grad_a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13
      complex(wp), allocatable :: tmp14(:), tmp15(:), tmp16(:), tmp17(:), tmp18(:), tmp19(:), &
                                  tmp86(:), tmp87(:), tmp88(:), tmp89(:)
      complex(wp) :: tmp1
      integer :: i, j

      if (state%matrix_free) then
         call dpcm_point_complex_mf_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[dpcm_point_complex_weights] call dpcm_point_complex_solve first")
         return
      end if
      if (any(shape(grad_r) /= [3, npt])) then
         call fatal_error(error, "[dpcm_point_complex_weights] grad_r: wrong shape")
         return
      end if
      if (any(shape(grad_n) /= [3, npt])) then
         call fatal_error(error, "[dpcm_point_complex_weights] grad_n: wrong shape")
         return
      end if
      if (any(shape(grad_k1) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_weights] grad_k1: wrong shape")
         return
      end if
      if (any(shape(grad_k2) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_weights] grad_k2: wrong shape")
         return
      end if
      if (any(shape(grad_a) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_weights] grad_a: wrong shape")
         return
      end if
      allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp86(npt), stat=stat)
      if (stat == 0) allocate (tmp87(npt), stat=stat)
      if (stat == 0) allocate (tmp88(npt), stat=stat)
      if (stat == 0) allocate (tmp89(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_complex_weights] allocation failed")
         return
      end if
      state%cx_ready = 3

      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c2 => state%s10
      tmp1 = state%cx_s2**(2)
      state%cx_s16 = 0.5_wp*tmp1
      state%cx_s17 = state%cx_s16*state%cx_s13
      state%cx_s18 = state%a*state%cx_s17
      state%cx_s19 = state%cx_s11*state%cx_s18
      do i = 1, npt
         tmp2 = 1.0_wp/state%a(i)
         tmp3 = 12.566370614359172_wp*tmp2
         tmp4 = sqrt(tmp3)
         tmp5 = (-0.26735_wp)*tmp4
         state%cx_s20(i) = tmp5
      end do
      do i = 1, npt
         tmp6 = 1.0_wp/state%a(i)
         tmp7 = 12.566370614359172_wp*tmp6
         tmp8 = 1.0_wp/sqrt(tmp7)
         tmp9 = state%k1(i) + state%k2(i)
         tmp10 = tmp8*tmp9
         tmp11 = state%a(i)**(-2)
         tmp12 = tmp10*tmp11
         tmp13 = 1.6798095918744622_wp*tmp12
         state%cx_s21(i) = tmp13
      end do
      tmp14 = 0.0_wp
      tmp15 = 0.0_wp
      tmp16 = 0.0_wp
      tmp17 = 0.0_wp
      tmp18 = 0.0_wp
      tmp19 = 0.0_wp
      !$omp parallel &
      !$omp& private(i, j) &
      !$omp& shared(npt, state, tmp17, tmp18, tmp19) &
      !$omp& reduction(+: tmp14, tmp15, tmp16) &
      !$omp& default(private)
      block
         real(wp) :: tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp34, tmp37, tmp41
         complex(wp) :: tmp32, tmp33, tmp20, tmp21, tmp22, tmp23, tmp24, tmp25

         !$omp do schedule(static)
         do j = 1, npt
            tmp26 = state%s4(j)
            tmp27 = state%s5(j)
            tmp28 = state%s6(j)
            tmp29 = state%s7(j)
            tmp30 = state%s8(j)
            tmp31 = state%s9(j)
            tmp32 = state%cx_s11(j)
            tmp33 = state%cx_s18(j)
            tmp34 = -tmp27
            tmp37 = -tmp28
            tmp41 = -tmp30
            tmp20 = 0.0_wp
            tmp21 = 0.0_wp
            tmp22 = 0.0_wp
            tmp23 = 0.0_wp
            tmp24 = 0.0_wp
            tmp25 = 0.0_wp
            !$omp simd &
            !$omp& reduction(+: tmp20, tmp21, tmp22, tmp23, tmp24, tmp25)
            do i = 1, j - 1
               block
                  real(wp) :: tmp35, tmp36, tmp38, tmp39, tmp40, tmp42, tmp43, tmp44, tmp45, &
                              tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, &
                              tmp55, tmp56, tmp57, tmp61, tmp62, tmp63, tmp64, tmp65, tmp69, &
                              tmp70, tmp71, tmp72, tmp73, tmp77, tmp80, tmp83
                  complex(wp) :: tmp58, tmp59, tmp60, tmp66, tmp67, tmp68, tmp74, tmp75, tmp76, &
                                 tmp78, tmp79, tmp81, tmp82, tmp84, tmp85

                  tmp35 = state%s5(i) + tmp34
                  tmp36 = tmp26*tmp35
                  tmp38 = state%s6(i) + tmp37
                  tmp39 = tmp38*tmp29
                  tmp40 = tmp36 + tmp39
                  tmp42 = state%s8(i) + tmp41
                  tmp43 = tmp42*tmp31
                  tmp44 = tmp40 + tmp43
                  tmp45 = tmp44*tmp35
                  tmp46 = tmp35**(2)
                  tmp47 = tmp38**(2)
                  tmp48 = tmp46 + tmp47
                  tmp49 = tmp42**(2)
                  tmp50 = tmp48 + tmp49
                  tmp51 = 1.0_wp/sqrt(tmp50)
                  tmp52 = tmp51**(5)
                  tmp53 = tmp45*tmp52
                  tmp54 = (-3.0_wp)*tmp53
                  tmp55 = tmp51**(3)
                  tmp56 = tmp26*tmp55
                  tmp57 = tmp54 + tmp56
                  tmp58 = tmp57*state%cx_s11(i)
                  tmp59 = tmp58*tmp33
                  tmp14(i) = tmp14(i) + tmp59
                  tmp60 = -tmp59
                  tmp20 = tmp20 + tmp60
                  tmp61 = tmp38*tmp44
                  tmp62 = tmp61*tmp52
                  tmp63 = (-3.0_wp)*tmp62
                  tmp64 = tmp29*tmp55
                  tmp65 = tmp63 + tmp64
                  tmp66 = tmp65*state%cx_s11(i)
                  tmp67 = tmp66*tmp33
                  tmp15(i) = tmp15(i) + tmp67
                  tmp68 = -tmp67
                  tmp21 = tmp21 + tmp68
                  tmp69 = tmp42*tmp44
                  tmp70 = tmp69*tmp52
                  tmp71 = (-3.0_wp)*tmp70
                  tmp72 = tmp31*tmp55
                  tmp73 = tmp71 + tmp72
                  tmp74 = tmp73*state%cx_s11(i)
                  tmp75 = tmp74*tmp33
                  tmp16(i) = tmp16(i) + tmp75
                  tmp76 = -tmp75
                  tmp22 = tmp22 + tmp76
                  tmp77 = tmp55*tmp35
                  tmp78 = tmp77*state%cx_s11(i)
                  tmp79 = tmp78*tmp33
                  tmp23 = tmp23 + tmp79
                  tmp80 = tmp38*tmp55
                  tmp81 = tmp80*state%cx_s11(i)
                  tmp82 = tmp81*tmp33
                  tmp24 = tmp24 + tmp82
                  tmp83 = tmp42*tmp55
                  tmp84 = tmp83*state%cx_s11(i)
                  tmp85 = tmp84*tmp33
                  tmp25 = tmp25 + tmp85
               end block
            end do
            !$omp simd &
            !$omp& reduction(+: tmp20, tmp21, tmp22, tmp23, tmp24, tmp25)
            do i = j + 1, npt
               block
                  real(wp) :: tmp35, tmp36, tmp38, tmp39, tmp40, tmp42, tmp43, tmp44, tmp45, &
                              tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, &
                              tmp55, tmp56, tmp57, tmp61, tmp62, tmp63, tmp64, tmp65, tmp69, &
                              tmp70, tmp71, tmp72, tmp73, tmp77, tmp80, tmp83
                  complex(wp) :: tmp58, tmp59, tmp60, tmp66, tmp67, tmp68, tmp74, tmp75, tmp76, &
                                 tmp78, tmp79, tmp81, tmp82, tmp84, tmp85

                  tmp35 = state%s5(i) + tmp34
                  tmp36 = tmp26*tmp35
                  tmp38 = state%s6(i) + tmp37
                  tmp39 = tmp38*tmp29
                  tmp40 = tmp36 + tmp39
                  tmp42 = state%s8(i) + tmp41
                  tmp43 = tmp42*tmp31
                  tmp44 = tmp40 + tmp43
                  tmp45 = tmp44*tmp35
                  tmp46 = tmp35**(2)
                  tmp47 = tmp38**(2)
                  tmp48 = tmp46 + tmp47
                  tmp49 = tmp42**(2)
                  tmp50 = tmp48 + tmp49
                  tmp51 = 1.0_wp/sqrt(tmp50)
                  tmp52 = tmp51**(5)
                  tmp53 = tmp45*tmp52
                  tmp54 = (-3.0_wp)*tmp53
                  tmp55 = tmp51**(3)
                  tmp56 = tmp26*tmp55
                  tmp57 = tmp54 + tmp56
                  tmp58 = tmp57*state%cx_s11(i)
                  tmp59 = tmp58*tmp33
                  tmp14(i) = tmp14(i) + tmp59
                  tmp60 = -tmp59
                  tmp20 = tmp20 + tmp60
                  tmp61 = tmp38*tmp44
                  tmp62 = tmp61*tmp52
                  tmp63 = (-3.0_wp)*tmp62
                  tmp64 = tmp29*tmp55
                  tmp65 = tmp63 + tmp64
                  tmp66 = tmp65*state%cx_s11(i)
                  tmp67 = tmp66*tmp33
                  tmp15(i) = tmp15(i) + tmp67
                  tmp68 = -tmp67
                  tmp21 = tmp21 + tmp68
                  tmp69 = tmp42*tmp44
                  tmp70 = tmp69*tmp52
                  tmp71 = (-3.0_wp)*tmp70
                  tmp72 = tmp31*tmp55
                  tmp73 = tmp71 + tmp72
                  tmp74 = tmp73*state%cx_s11(i)
                  tmp75 = tmp74*tmp33
                  tmp16(i) = tmp16(i) + tmp75
                  tmp76 = -tmp75
                  tmp22 = tmp22 + tmp76
                  tmp77 = tmp55*tmp35
                  tmp78 = tmp77*state%cx_s11(i)
                  tmp79 = tmp78*tmp33
                  tmp23 = tmp23 + tmp79
                  tmp80 = tmp38*tmp55
                  tmp81 = tmp80*state%cx_s11(i)
                  tmp82 = tmp81*tmp33
                  tmp24 = tmp24 + tmp82
                  tmp83 = tmp42*tmp55
                  tmp84 = tmp83*state%cx_s11(i)
                  tmp85 = tmp84*tmp33
                  tmp25 = tmp25 + tmp85
               end block
            end do
            tmp14(j) = tmp14(j) + tmp20
            tmp15(j) = tmp15(j) + tmp21
            tmp16(j) = tmp16(j) + tmp22
            tmp17(j) = tmp17(j) + tmp23
            tmp18(j) = tmp18(j) + tmp24
            tmp19(j) = tmp19(j) + tmp25
         end do
         !$omp end do
      end block
      !$omp end parallel
      grad_r(1, :) = tmp14
      grad_r(2, :) = tmp15
      grad_r(3, :) = tmp16
      grad_n(1, :) = tmp17
      grad_n(2, :) = tmp18
      grad_n(3, :) = tmp19
      grad_k1 = state%cx_s19*state%cx_s20
      grad_k2 = grad_k1
      tmp86 = state%cx_s14*state%cx_vn
      tmp87 = state%cx_s19*state%cx_s21
      tmp88 = tmp86 + tmp87
      tmp89 = state%cx_s17*state%cx_s15
      grad_a = tmp88 + tmp89

      state%cx_ready = 4
   end subroutine dpcm_point_complex_weights

   !> DPCM (point charges): gradient tangents along blocks of directions
   !>
   !> - Directions of the cavity and QM inputs; for the inputs of the last solve
   !> - Needs dpcm_point_complex_weights on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[in] dr  direction for r
   !> @param[in] dn  direction for n
   !> @param[in] dk1  direction for k1
   !> @param[in] dk2  direction for k2
   !> @param[in] da  direction for a
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_r  hessian times direction, r block
   !> @param[out] hvp_n  hessian times direction, n block
   !> @param[out] hvp_k1  hessian times direction, k1 block
   !> @param[out] hvp_k2  hessian times direction, k2 block
   !> @param[out] hvp_a  hessian times direction, a block
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_complex_tangent(state, dr, dn, dk1, dk2, da, dv, dvn, hvp_r, hvp_n, &
