   !> DPCM (point charges): linear response of the v, vn gradient
   !>
   !> - Directions of v, vn only; the state is not changed
   !> - Needs dpcm_point_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_point
      type(dpcm_point_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%ready < 3) then
         call fatal_error(error, "[dpcm_point_mf_response] call dpcm_point_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_point_mf_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_point_mf_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_point_mf_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_point_mf_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_point_mf_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                         hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_point_mf_response

   !> One direction of dpcm_point_mf_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_mf_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of dpcm_point
      type(dpcm_point_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_point_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_mf_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_point_mf_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_mf_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_mf_response_one] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%a => state%a
      tmp1 = state%a*dvn
      tmp2 = 0.0_wp
      call state%solver%solve(state%op2, .false., tmp1, tmp2, error)
      if (allocated(error)) return
      hvp_v = state%s12*tmp2
      tmp3 = 0.0_wp
      call state%solver%solve(state%op2, .true., dv, tmp3, error)
      if (allocated(error)) return
      tmp4 = state%s12*tmp3
      hvp_vn = tmp4*state%a
   end subroutine dpcm_point_mf_response_one

   !> DPCM (point charges): energy derivatives with respect to the solvent parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs dpcm_point_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_mf_param_weights(state, grad_eps, error)
      !> State of dpcm_point
      type(dpcm_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      real(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp5(:), tmp6(:)
      real(wp) :: tmp1, tmp3, tmp4, tmp7, tmp8, tmp9, tmp10

      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, "[dpcm_point_mf_param_weights] call dpcm_point_solve first")
         return
      end if
      allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_mf_param_weights] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%a => state%a
      tmp1 = state%s1**(-2)
      tmp2 = 0.5_wp*state%v
      tmp3 = dot(tmp2, state%s11)
      tmp4 = (-0.5_wp)*state%s2
      tmp5 = tmp4*state%s13
      tmp6 = state%a*state%s15
      tmp7 = dot(tmp5, tmp6)
      tmp8 = -tmp7
      tmp9 = tmp3 + tmp8
      tmp10 = tmp1*tmp9
      grad_eps = 2.0_wp*tmp10
   end subroutine dpcm_point_mf_param_weights

   !> DPCM (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs dpcm_point_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_complex_mf_medium(state, eps, error)
      !> State of dpcm_point
      type(dpcm_point_complex_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      complex(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp) :: tmp1, tmp2

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[dpcm_point_complex_mf_medium] call dpcm_point_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_vn)) deallocate (state%cx_vn)
      if (allocated(state%cx_s11)) deallocate (state%cx_s11)
      if (allocated(state%cx_s13)) deallocate (state%cx_s13)
      if (allocated(state%cx_s14)) deallocate (state%cx_s14)
      if (allocated(state%cx_s15)) deallocate (state%cx_s15)
      if (allocated(state%cx_s17)) deallocate (state%cx_s17)
      if (allocated(state%cx_s18)) deallocate (state%cx_s18)
      if (allocated(state%cx_s19)) deallocate (state%cx_s19)
      if (allocated(state%cx_s20)) deallocate (state%cx_s20)
      if (allocated(state%cx_s21)) deallocate (state%cx_s21)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_vn(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s11(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s13(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s14(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s15(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s17(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s20(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_complex_mf_medium] allocation failed")
         return
      end if
      state%cx_s11 = 0.0_wp
      state%cx_s13 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op4%npt = npt
      state%op4%npoint = npt
      state%op4%id = 4
      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%cx_s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%cx_s1
      tmp2 = (-2.0_wp)*tmp1
      state%cx_s2 = 1.0_wp + tmp2
      state%cx_s3 = -state%cx_s2
      state%op4%c1 = state%cx_s3
      call state%solver%setup_complex(state%op4, error)
      if (allocated(error)) return
      state%cx_s12 = 0.5_wp*state%cx_s2

      state%cx_ready = 2
   end subroutine dpcm_point_complex_mf_medium

   !> DPCM (point charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs dpcm_point_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_complex_mf_solve(state, v, vn, energy, q, grad_v, grad_vn, error)
      !> State of dpcm_point
      type(dpcm_point_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
      complex(wp), contiguous, intent(in) :: vn(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      complex(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp3(:)
      real(wp) :: tmp4, tmp5, tmp6, tmp7, tmp8, tmp9
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp10(:), tmp40(:), tmp41(:), tmp42(:), &
                                  tmp43(:), tmp44(:), tmp45(:)
      complex(wp) :: tmp39, tmp46
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_point_complex_mf_solve] call dpcm_point_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_mf_solve] vn: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_mf_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_mf_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp40(npt), stat=stat)
      if (stat == 0) allocate (tmp41(npt), stat=stat)
      if (stat == 0) allocate (tmp42(npt), stat=stat)
      if (stat == 0) allocate (tmp43(npt), stat=stat)
      if (stat == 0) allocate (tmp44(npt), stat=stat)
      if (stat == 0) allocate (tmp45(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_complex_mf_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      state%cx_v = v
      state%cx_vn = vn
      tmp1 = state%a*state%cx_vn
      call state%solver%solve_complex(state%op4, .false., tmp1, state%cx_s11, error)
      if (allocated(error)) return
      call state%solver%solve_complex(state%op4, .true., state%cx_v, state%cx_s13, error)
      if (allocated(error)) return
      state%cx_s14 = state%cx_s12*state%cx_s13
      do i = 1, npt
         tmp4 = state%k1(i) + state%k2(i)
         tmp5 = 1.0_wp/state%a(i)
         tmp6 = 12.566370614359172_wp*tmp5
         tmp7 = sqrt(tmp6)
         tmp8 = tmp4*tmp7
         tmp9 = (-0.26735_wp)*tmp8
         tmp3(i) = tmp9
      end do
      tmp10 = tmp3*state%cx_s11
      tmp2 = tmp10
      !$omp parallel &
      !$omp& private(i, j) &
      !$omp& shared(npt, state, tmp2) &
      !$omp& default(private)
      block
         real(wp) :: tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp19, tmp22, tmp26
         complex(wp) :: tmp18, tmp11

         !$omp do schedule(static)
         do j = 1, npt
            tmp12 = state%s4(j)
            tmp13 = state%s5(j)
            tmp14 = state%s6(j)
            tmp15 = state%s7(j)
            tmp16 = state%s8(j)
            tmp17 = state%s9(j)
            tmp18 = state%cx_s11(j)
            tmp19 = -tmp13
            tmp22 = -tmp14
            tmp26 = -tmp16
            tmp11 = 0.0_wp
            !$omp simd &
            !$omp& reduction(+: tmp11)
            do i = 1, j - 1
               block
                  real(wp) :: tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp30, &
                              tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37
                  complex(wp) :: tmp38

                  tmp20 = state%s5(i) + tmp19
                  tmp21 = tmp12*tmp20
                  tmp23 = state%s6(i) + tmp22
                  tmp24 = tmp23*tmp15
                  tmp25 = tmp21 + tmp24
                  tmp27 = state%s8(i) + tmp26
                  tmp28 = tmp27*tmp17
                  tmp29 = tmp25 + tmp28
                  tmp30 = tmp20**(2)
                  tmp31 = tmp23**(2)
                  tmp32 = tmp30 + tmp31
                  tmp33 = tmp27**(2)
                  tmp34 = tmp32 + tmp33
                  tmp35 = 1.0_wp/sqrt(tmp34)
                  tmp36 = tmp35**(3)
                  tmp37 = tmp29*tmp36
                  tmp38 = tmp37*state%cx_s11(i)
                  tmp11 = tmp11 + tmp38
               end block
            end do
            !$omp simd &
            !$omp& reduction(+: tmp11)
            do i = j + 1, npt
               block
                  real(wp) :: tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp30, &
                              tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37
                  complex(wp) :: tmp38

                  tmp20 = state%s5(i) + tmp19
                  tmp21 = tmp12*tmp20
                  tmp23 = state%s6(i) + tmp22
                  tmp24 = tmp23*tmp15
                  tmp25 = tmp21 + tmp24
                  tmp27 = state%s8(i) + tmp26
                  tmp28 = tmp27*tmp17
                  tmp29 = tmp25 + tmp28
                  tmp30 = tmp20**(2)
                  tmp31 = tmp23**(2)
                  tmp32 = tmp30 + tmp31
                  tmp33 = tmp27**(2)
                  tmp34 = tmp32 + tmp33
                  tmp35 = 1.0_wp/sqrt(tmp34)
                  tmp36 = tmp35**(3)
                  tmp37 = tmp29*tmp36
                  tmp38 = tmp37*state%cx_s11(i)
                  tmp11 = tmp11 + tmp38
               end block
            end do
            tmp2(j) = tmp2(j) + tmp11
         end do
         !$omp end do
      end block
      !$omp end parallel
      state%cx_s15 = tmp2
      q = state%cx_s2*state%cx_s11
      tmp39 = sum(state%cx_v*q)
      energy = 0.5_wp*tmp39
      grad_v = state%cx_s12*state%cx_s11
      grad_vn = state%cx_s14*state%a
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp40 = 6.283185307179586_wp*state%cx_s11
         tmp41 = state%a*state%cx_s15
         tmp42 = state%cx_s3*tmp41
         tmp43 = tmp40 + tmp42
         tmp44 = -tmp43
         tmp45 = tmp1 + tmp44
         tmp46 = sum(state%cx_s14*tmp45)
         energy = energy + tmp46
      end if

      state%cx_ready = 3
   end subroutine dpcm_point_complex_mf_solve

   !> DPCM (point charges): energy gradient with respect to the cavity inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs dpcm_point_complex_solve on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
