      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_mf_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_mf_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[dpcm_point_complex_mf_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_complex_mf_response_one] allocation failed")
         return
      end if

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      tmp1 = state%a*dvn
      tmp2 = 0.0_wp
      call state%solver%solve_complex(state%op4, .false., tmp1, tmp2, error)
      if (allocated(error)) return
      hvp_v = state%cx_s12*tmp2
      tmp3 = 0.0_wp
      call state%solver%solve_complex(state%op4, .true., dv, tmp3, error)
      if (allocated(error)) return
      tmp4 = state%cx_s12*tmp3
      hvp_vn = tmp4*state%a
   end subroutine dpcm_point_complex_mf_response_one

   !> DPCM (point charges): energy derivatives with respect to the solvent parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs dpcm_point_complex_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_point
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_point_complex_mf_param_weights(state, grad_eps, error)
      !> State of dpcm_point
      type(dpcm_point_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      complex(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp2(:), tmp5(:), tmp6(:)
      complex(wp) :: tmp1, tmp3, tmp4, tmp7, tmp8, tmp9, tmp10

      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_point_complex_mf_param_weights] call dpcm_point_complex_solve first")
         return
      end if
      allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_complex_mf_param_weights] allocation failed")
         return
      end if

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%a => state%a
      tmp1 = state%cx_s1**(-2)
      tmp2 = 0.5_wp*state%cx_v
      tmp3 = sum(tmp2*state%cx_s11)
      tmp4 = (-0.5_wp)*state%cx_s2
      tmp5 = tmp4*state%cx_s13
      tmp6 = state%a*state%cx_s15
      tmp7 = sum(tmp5*tmp6)
      tmp8 = -tmp7
      tmp9 = tmp3 + tmp8
      tmp10 = tmp1*tmp9
      grad_eps = 2.0_wp*tmp10
   end subroutine dpcm_point_complex_mf_param_weights

   !> Apply operator 1 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_point_op1_apply(self, trans, x, y)
      !> Operator
      class(dpcm_point_op1), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp3(self%npt))
            allocate (tmp4(self%npt))
            tmp1 = 6.283185307179586_wp*x
            tmp2 = self%a*x
            call gemv(self%c2, tmp2, tmp3)
            tmp4 = self%c1*tmp3
            y = tmp1 + tmp4
         end block
      else
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:)

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp3(self%npt))
            allocate (tmp4(self%npt))
            tmp1 = 6.283185307179586_wp*x
            call gemv(self%c2, x, tmp2, trans="t")
            tmp3 = self%a*tmp2
            tmp4 = self%c1*tmp3
            y = tmp1 + tmp4
         end block
      end if
   end subroutine dpcm_point_op1_apply

   !> Form operator 1 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine dpcm_point_op1_assemble(self, a, error)
      !> Operator
      class(dpcm_point_op1), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp4(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp5(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_op1_assemble] allocation failed")
         return
      end if
      tmp1 = 0.0_wp
      do i = 1, self%npt
         tmp1(i, i) = 1.0_wp
      end do
      tmp2 = 6.283185307179586_wp*tmp1
      tmp3 = transpose(self%c2)
      do i = 1, self%npt
         tmp4(:, i) = self%a*tmp3(:, i)
      end do
      tmp5 = self%c1*tmp4
      a = tmp2 + tmp5
   end subroutine dpcm_point_op1_assemble

   !> Form operator 1 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine dpcm_point_op1_assemble_block(self, idx, a, error)
      !> Operator
      class(dpcm_point_op1), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp), allocatable :: tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :), tmp6(:, :), &
                               tmp7(:, :)
      integer :: i

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[dpcm_point_op1_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp7(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_op1_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%a(idx)
      tmp2 = self%c2(idx, idx)
      tmp3 = 0.0_wp
      do i = 1, nb
         tmp3(i, i) = 1.0_wp
      end do
      tmp4 = 6.283185307179586_wp*tmp3
      tmp5 = transpose(tmp2)
      do i = 1, nb
         tmp6(:, i) = tmp1*tmp5(:, i)
      end do
      tmp7 = self%c1*tmp6
      a = tmp4 + tmp7
   end subroutine dpcm_point_op1_assemble_block

   !> Apply operator 2 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_point_op2_apply(self, trans, x, y)
      !> Operator
      class(dpcm_point_op2), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp11(:), tmp39(:)
            real(wp) :: tmp5, tmp6, tmp7, tmp8, tmp9, tmp10
            integer :: i, j

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp3(self%npt))
            allocate (tmp4(self%npt))
            allocate (tmp11(self%npt))
            allocate (tmp39(self%npt))
            tmp1 = 6.283185307179586_wp*x
            tmp2 = self%a*x
            do i = 1, self%npt
               tmp5 = self%k1(i) + self%k2(i)
               tmp6 = 1.0_wp/self%a(i)
               tmp7 = 12.566370614359172_wp*tmp6
               tmp8 = sqrt(tmp7)
               tmp9 = tmp5*tmp8
               tmp10 = (-0.26735_wp)*tmp9
               tmp4(i) = tmp10
            end do
            tmp11 = tmp4*tmp2
            tmp3 = tmp11
            !$omp parallel &
            !$omp& private(i, j) &
            !$omp& shared(self, tmp2) &
            !$omp& reduction(+: tmp3) &
            !$omp& default(private)
            block
               real(wp) :: tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp22, tmp26

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp12 = self%n(1, j)
                  tmp13 = self%r(1, j)
                  tmp14 = self%r(2, j)
                  tmp15 = self%n(2, j)
                  tmp16 = self%r(3, j)
                  tmp17 = self%n(3, j)
                  tmp18 = tmp2(j)
                  tmp19 = -tmp13
                  tmp22 = -tmp14
                  tmp26 = -tmp16
                  !$omp simd
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp30, &
                                    tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38

                        tmp20 = self%r(1, i) + tmp19
                        tmp21 = tmp12*tmp20
                        tmp23 = self%r(2, i) + tmp22
                        tmp24 = tmp23*tmp15
                        tmp25 = tmp21 + tmp24
                        tmp27 = self%r(3, i) + tmp26
                        tmp28 = tmp27*tmp17
                        tmp29 = tmp25 + tmp28
                        tmp30 = tmp20**(2)
                        tmp31 = tmp23**(2)
                        tmp32 = tmp30 + tmp31
                        tmp33 = tmp27**(2)
                        tmp34 = tmp32 + tmp33
                        tmp35 = 1.0_wp/sqrt(tmp34)
                        tmp36 = tmp35**(3)
                        tmp37 = tmp29*tmp36
                        tmp38 = tmp37*tmp18
                        tmp3(i) = tmp3(i) + tmp38
                     end block
                  end do
                  !$omp simd
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp30, &
                                    tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38

                        tmp20 = self%r(1, i) + tmp19
                        tmp21 = tmp12*tmp20
                        tmp23 = self%r(2, i) + tmp22
                        tmp24 = tmp23*tmp15
                        tmp25 = tmp21 + tmp24
                        tmp27 = self%r(3, i) + tmp26
                        tmp28 = tmp27*tmp17
                        tmp29 = tmp25 + tmp28
                        tmp30 = tmp20**(2)
                        tmp31 = tmp23**(2)
                        tmp32 = tmp30 + tmp31
                        tmp33 = tmp27**(2)
                        tmp34 = tmp32 + tmp33
                        tmp35 = 1.0_wp/sqrt(tmp34)
                        tmp36 = tmp35**(3)
                        tmp37 = tmp29*tmp36
                        tmp38 = tmp37*tmp18
                        tmp3(i) = tmp3(i) + tmp38
                     end block
                  end do
               end do
               !$omp end do
            end block
            !$omp end parallel
            tmp39 = self%c1*tmp3
            y = tmp1 + tmp39
         end block
      else
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp10(:), tmp39(:), tmp40(:)
            real(wp) :: tmp4, tmp5, tmp6, tmp7, tmp8, tmp9
            integer :: i, j

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp3(self%npt))
            allocate (tmp10(self%npt))
            allocate (tmp39(self%npt))
            allocate (tmp40(self%npt))
            tmp1 = 6.283185307179586_wp*x
            do i = 1, self%npt
               tmp4 = self%k1(i) + self%k2(i)
               tmp5 = 1.0_wp/self%a(i)
               tmp6 = 12.566370614359172_wp*tmp5
               tmp7 = sqrt(tmp6)
               tmp8 = tmp4*tmp7
               tmp9 = (-0.26735_wp)*tmp8
               tmp3(i) = tmp9
            end do
            tmp10 = tmp3*x
            tmp2 = tmp10
            !$omp parallel &
            !$omp& private(i, j) &
            !$omp& shared(self, tmp2, x) &
            !$omp& default(private)
            block
               real(wp) :: tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp22, tmp26, &
                           tmp11

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp12 = x(j)
                  tmp13 = self%n(1, j)
                  tmp14 = self%r(1, j)
                  tmp15 = self%r(2, j)
                  tmp16 = self%n(2, j)
                  tmp17 = self%r(3, j)
                  tmp18 = self%n(3, j)
                  tmp19 = -tmp14
                  tmp22 = -tmp15
                  tmp26 = -tmp17
                  tmp11 = 0.0_wp
                  !$omp simd &
                  !$omp& reduction(+: tmp11)
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp30, &
                                    tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38

                        tmp20 = self%r(1, i) + tmp19
                        tmp21 = tmp13*tmp20
                        tmp23 = self%r(2, i) + tmp22
                        tmp24 = tmp23*tmp16
                        tmp25 = tmp21 + tmp24
                        tmp27 = self%r(3, i) + tmp26
                        tmp28 = tmp27*tmp18
                        tmp29 = tmp25 + tmp28
                        tmp30 = x(i)*tmp29
                        tmp31 = tmp20**(2)
                        tmp32 = tmp23**(2)
                        tmp33 = tmp31 + tmp32
                        tmp34 = tmp27**(2)
                        tmp35 = tmp33 + tmp34
                        tmp36 = 1.0_wp/sqrt(tmp35)
                        tmp37 = tmp36**(3)
                        tmp38 = tmp30*tmp37
                        tmp11 = tmp11 + tmp38
                     end block
                  end do
                  !$omp simd &
                  !$omp& reduction(+: tmp11)
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, tmp30, &
                                    tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38

                        tmp20 = self%r(1, i) + tmp19
                        tmp21 = tmp13*tmp20
                        tmp23 = self%r(2, i) + tmp22
                        tmp24 = tmp23*tmp16
                        tmp25 = tmp21 + tmp24
                        tmp27 = self%r(3, i) + tmp26
                        tmp28 = tmp27*tmp18
                        tmp29 = tmp25 + tmp28
                        tmp30 = x(i)*tmp29
                        tmp31 = tmp20**(2)
                        tmp32 = tmp23**(2)
                        tmp33 = tmp31 + tmp32
                        tmp34 = tmp27**(2)
                        tmp35 = tmp33 + tmp34
                        tmp36 = 1.0_wp/sqrt(tmp35)
                        tmp37 = tmp36**(3)
                        tmp38 = tmp30*tmp37
                        tmp11 = tmp11 + tmp38
                     end block
                  end do
                  tmp2(j) = tmp2(j) + tmp11
               end do
               !$omp end do
            end block
            !$omp end parallel
            tmp39 = self%a*tmp2
            tmp40 = self%c1*tmp39
            y = tmp1 + tmp40
         end block
      end if
   end subroutine dpcm_point_op2_apply

   !> Form operator 2 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine dpcm_point_op2_assemble(self, a, error)
      !> Operator
      class(dpcm_point_op2), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :), tmp38(:, :), tmp39(:, :), &
                               tmp40(:, :)
      real(wp) :: tmp32, tmp33, tmp34, tmp35, tmp36, tmp37
      integer :: i, j

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp38(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp39(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp40(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_op2_assemble] allocation failed")
         return
      end if
      tmp1 = 0.0_wp
      do i = 1, self%npt
         tmp1(i, i) = 1.0_wp
      end do
      tmp2 = 6.283185307179586_wp*tmp1
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(self, tmp3)
      do j = 1, self%npt
         block
            real(wp) :: tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, tmp14, &
                        tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, tmp23, tmp24, &
                        tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31

            do i = 1, j - 1
               tmp4 = -self%r(1, j)
               tmp5 = self%r(1, i) + tmp4
               tmp6 = self%n(1, j)*tmp5
               tmp7 = -self%r(2, j)
               tmp8 = self%r(2, i) + tmp7
               tmp9 = tmp8*self%n(2, j)
               tmp10 = tmp6 + tmp9
               tmp11 = -self%r(3, j)
               tmp12 = self%r(3, i) + tmp11
               tmp13 = tmp12*self%n(3, j)
               tmp14 = tmp10 + tmp13
               tmp15 = tmp5**(2)
               tmp16 = tmp8**(2)
               tmp17 = tmp15 + tmp16
               tmp18 = tmp12**(2)
               tmp19 = tmp17 + tmp18
               tmp20 = 1.0_wp/sqrt(tmp19)
               tmp21 = tmp20**(3)
               tmp22 = tmp14*tmp21
               tmp3(i, j) = tmp22
               tmp23 = -tmp5
               tmp24 = self%n(1, i)*tmp23
               tmp25 = -tmp8
               tmp26 = tmp25*self%n(2, i)
               tmp27 = tmp24 + tmp26
               tmp28 = -tmp12
               tmp29 = tmp28*self%n(3, i)
               tmp30 = tmp27 + tmp29
               tmp31 = tmp30*tmp21
               tmp3(j, i) = tmp31
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, self%npt
         tmp32 = self%k1(i) + self%k2(i)
         tmp33 = 1.0_wp/self%a(i)
         tmp34 = 12.566370614359172_wp*tmp33
         tmp35 = sqrt(tmp34)
         tmp36 = tmp32*tmp35
         tmp37 = (-0.26735_wp)*tmp36
         tmp3(i, i) = tmp37
      end do
      tmp38 = transpose(tmp3)
      do i = 1, self%npt
         tmp39(:, i) = self%a*tmp38(:, i)
      end do
      tmp40 = self%c1*tmp39
      a = tmp2 + tmp40
   end subroutine dpcm_point_op2_assemble

   !> Form operator 2 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine dpcm_point_op2_assemble_block(self, idx, a, error)
      !> Operator
      class(dpcm_point_op2), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp5(:)
      real(wp), allocatable :: tmp6(:, :), tmp7(:, :), tmp8(:, :), tmp43(:, :), tmp44(:, :), &
                               tmp45(:, :)
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :)
      real(wp) :: tmp37, tmp38, tmp39, tmp40, tmp41, tmp42
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[dpcm_point_op2_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(3, nb), stat=stat)
      if (stat == 0) allocate (tmp2(3, nb), stat=stat)
