      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_op3_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%a(idx)
      tmp2 = self%c2(idx, idx)
      tmp3 = 0.0_wp
      do i = 1, nb
