   end subroutine dpcm_point_op3_assemble_block

   !> Apply operator 4 or its transpose (not conjugated)
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine dpcm_point_op4_apply(self, trans, x, y)
      !> Operator
      class(dpcm_point_op4), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
