                  tmp13 = self%r(1, j)
                  tmp14 = self%r(2, j)
                  tmp15 = self%n(2, j)
                  tmp16 = self%r(3, j)
                  tmp17 = self%n(3, j)
                  tmp18 = tmp2(j)
                  tmp19 = -tmp13
                  tmp22 = -tmp14
                  tmp26 = -tmp16
                  !$omp simd
