                        tmp21 = tmp12*tmp20
                        tmp23 = self%r(2, i) + tmp22
                        tmp24 = tmp23*tmp15
                        tmp25 = tmp21 + tmp24
                        tmp27 = self%r(3, i) + tmp26
                        tmp28 = tmp27*tmp17
                        tmp29 = tmp25 + tmp28
