               tmp23 = -tmp5
               tmp24 = self%n(1, i)*tmp23
               tmp25 = -tmp8
               tmp26 = tmp25*self%n(2, i)
               tmp27 = tmp24 + tmp26
               tmp28 = -tmp12
               tmp29 = tmp28*self%n(3, i)
               tmp30 = tmp27 + tmp29
               tmp31 = tmp30*tmp21
