      complex(wp), allocatable :: tmp45(:, :)
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[dpcm_point_op4_assemble_block] a: wrong shape")
