      if (stat == 0) allocate (tmp7(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp8(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp43(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp44(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp45(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_point_op4_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%r(:, idx)
      tmp2 = self%n(:, idx)
      tmp3 = self%k1(idx)
      tmp4 = self%k2(idx)
      tmp5 = self%a(idx)
      tmp6 = 0.0_wp
      do i = 1, nb
         tmp6(i, i) = 1.0_wp
      end do
      tmp7 = 6.283185307179586_wp*tmp6
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(nb, tmp1, tmp2, tmp8)
      do j = 1, nb
         block
            real(wp) :: tmp9, tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, &
                        tmp19, tmp20, tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, &
                        tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36

            do i = 1, j - 1
               tmp9 = -tmp1(1, j)
               tmp10 = tmp1(1, i) + tmp9
               tmp11 = tmp2(1, j)*tmp10
               tmp12 = -tmp1(2, j)
               tmp13 = tmp1(2, i) + tmp12
               tmp14 = tmp13*tmp2(2, j)
               tmp15 = tmp11 + tmp14
               tmp16 = -tmp1(3, j)
               tmp17 = tmp1(3, i) + tmp16
               tmp18 = tmp17*tmp2(3, j)
               tmp19 = tmp15 + tmp18
               tmp20 = tmp10**(2)
               tmp21 = tmp13**(2)
               tmp22 = tmp20 + tmp21
               tmp23 = tmp17**(2)
               tmp24 = tmp22 + tmp23
               tmp25 = 1.0_wp/sqrt(tmp24)
               tmp26 = tmp25**(3)
               tmp27 = tmp19*tmp26
               tmp8(i, j) = tmp27
               tmp28 = -tmp10
               tmp29 = tmp2(1, i)*tmp28
               tmp30 = -tmp13
               tmp31 = tmp30*tmp2(2, i)
               tmp32 = tmp29 + tmp31
               tmp33 = -tmp17
               tmp34 = tmp33*tmp2(3, i)
               tmp35 = tmp32 + tmp34
               tmp36 = tmp35*tmp26
               tmp8(j, i) = tmp36
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, nb
         tmp37 = tmp3(i) + tmp4(i)
         tmp38 = 1.0_wp/tmp5(i)
         tmp39 = 12.566370614359172_wp*tmp38
         tmp40 = sqrt(tmp39)
         tmp41 = tmp37*tmp40
         tmp42 = (-0.26735_wp)*tmp41
         tmp8(i, i) = tmp42
      end do
      tmp43 = transpose(tmp8)
      do i = 1, nb
         tmp44(:, i) = tmp5*tmp43(:, i)
      end do
      tmp45 = self%c1*tmp44
      a = tmp7 + tmp45
   end subroutine dpcm_point_op4_assemble_block

end module pcmgen_point_dpcm
